js.input:
@property --tone {
                syntax: "<color>";
                inherits: false;
                initial-value: oklch(60% 0.1 30);
            }
            @function --double(--x <number>: 1) {
                result: calc(var(--x) * 2);
            }
            @media (width > 30rem) {
                .sample { color: var(--tone); }
                @keyframes pulse {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }
            }

